import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";import{rt as i}from"./chunks/assets.DeBnt35C.js";var a=JSON.parse(`{"title":"持久化","description":"","frontmatter":{},"headers":[],"relativePath":"database/redis/basic/persistence.md","filePath":"database/redis/basic/persistence.md"}`),o={name:`database/redis/basic/persistence.md`};function s(r,a,o,s,c,l){return n(),e(`div`,null,[...a[0]||=[t(`<h1 id="持久化" tabindex="-1">持久化 <a class="header-anchor" href="#持久化" aria-label="Permalink to “持久化”">​</a></h1><ul><li>就是永久保存数据到磁盘上，避免服务宕机导致数据丢失。</li></ul><h2 id="为啥要持久化" tabindex="-1">为啥要持久化？ <a class="header-anchor" href="#为啥要持久化" aria-label="Permalink to “为啥要持久化？”">​</a></h2><ul><li>Redis 是个基于内存的数据库，一旦宕机，内存中的数据将全部丢失。</li><li>通常的解决方案是从后端数据库恢复这些数据，但后端数据库有性能瓶颈，如果是大数据量的恢复， <ul><li>会对数据库带来巨大的压力</li><li>数据库的性能不如 Redis。导致程序响应慢。</li></ul></li><li>所以对 Redis 来说，实现数据的持久化，避免从后端数据库中恢复数据，是至关重要的。</li></ul><h2 id="rdb-快照方式" tabindex="-1">RDB-快照方式 <a class="header-anchor" href="#rdb-快照方式" aria-label="Permalink to “RDB-快照方式”">​</a></h2><ul><li>RDB 持久化是把当前进程数据生成快照保存到磁盘上的过程，由于是某一时刻的快照，那么快照中的值要早于或者等于内存中的值。</li></ul><h3 id="触发方式" tabindex="-1">触发方式 <a class="header-anchor" href="#触发方式" aria-label="Permalink to “触发方式”">​</a></h3><ul><li>手动触发： <ul><li><code>save</code> 命令：阻塞当前 <code>Redis</code> 服务器，直到 <code>RDB</code> 过程完成为止，对于内存 比较大的实例会造成长时间阻塞，线上环境不建议使用。</li><li><code>bgsave</code> 命令：<code>Redis</code> 进程执行 <code>fork</code> 操作创建子进程，<code>RDB</code> 持久化过程由子 进程负责，完成后自动结束。阻塞只发生在 <code>fork</code> 阶段，一般时间很短。</li></ul></li><li>自动触发： <ul><li><code>redis.conf</code> 中配置 <code>save m n</code>，即在 <code>m</code> 秒内有 <code>n</code> 次修改时，自动触发 <code>bgsave</code> 生成 <code>rdb</code> 文件。</li><li>主从复制时，从节点要从主节点进行全量复制时也会触发 <code>bgsave</code> 操作，生成当时的快照发送到从节点。</li><li>执行 <code>debug reload</code> 命令重新加载 <code>redis</code> 时也会触发 <code>bgsave</code> 操作。</li><li>默认情况下执行 <code>shutdown</code> 命令时，如果没有开启 <code>aof</code> 持久化，那么也会触发 <code>bgsave</code> 操作。</li></ul></li></ul><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><ul><li><code>RDB</code> 文件是某个时间节点的快照，默认使用 <code>LZF</code> 算法进行压缩，压缩后的文件体积远远小于内存大小，适用于备份、全量复制等场景。</li><li><code>Redis</code> 加载 <code>RDB</code> 文件恢复数据要远远快于 <code>AOF</code> 方式；</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><ul><li><code>RDB</code> 方式实时性不够，无法做到秒级的持久化。</li><li>每次调用 <code>bgsave</code> 都需要 <code>fork</code> 子进程，<code>fork</code> 子进程属于重量级操作，频繁执行成本较高。</li><li><code>RDB</code> 文件是二进制的，没有可读性，<code>AOF</code> 文件在了解其结构的情况下可以手动修改或者补全。</li></ul><h2 id="aof-日志模式" tabindex="-1">AOF-日志模式 <a class="header-anchor" href="#aof-日志模式" aria-label="Permalink to “AOF-日志模式”">​</a></h2><ul><li><code>Redis</code> 是“写后”日志，<code>Redis</code>先执行命令，把数据写入内存，然后才记录日志。</li><li>日志里记录的是 <code>Redis</code> 收到的每一条命令，这些命令是以文本形式保存。</li></ul><h3 id="实现方式" tabindex="-1">实现方式 <a class="header-anchor" href="#实现方式" aria-label="Permalink to “实现方式”">​</a></h3><ul><li>默认情况下，<code>Redis</code> 是没有开启 <code>AOF</code> 的，可以通过配置 <code>redis.conf</code> 文件来开启 AOF 持久化。</li></ul><table tabindex="0"><thead><tr><th>配置参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>appendonly</td><td>no</td><td>是否开启 <code>AOF</code> 功能，默认是关闭的。</td></tr><tr><td>appendfilename</td><td>appendonly.aof</td><td>配置 <code>AOF</code> 文件的名字。</td></tr><tr><td>appendfsync</td><td>everysec</td><td>同步策略 <br> <code>always</code> 同步写回：每个写命令执行完，立马同步地将日志写回磁盘 <br> <code>everysec</code> 每秒写回：每个写命令执行完，只是先把日志写到 AOF 文件的内存缓冲区，每隔一秒把缓冲区中的内容写入磁盘 <br> <code>no</code> 由操作系统决定何时将缓冲区内容写回磁盘。</td></tr></tbody></table><h2 id="rdb-aof-混合模式" tabindex="-1">RDB+AOF 混合模式 <a class="header-anchor" href="#rdb-aof-混合模式" aria-label="Permalink to “RDB+AOF 混合模式”">​</a></h2><ul><li>简单来说，内存快照以一定的频率执行，在两次快照之间，使用 <code>AOF</code> 日志记录这期间的所有命令操作。</li></ul><h2 id="如何恢复数据" tabindex="-1">如何恢复数据？ <a class="header-anchor" href="#如何恢复数据" aria-label="Permalink to “如何恢复数据？”">​</a></h2><ul><li><code>redis</code> 重启时会自动执行恢复程序</li></ul><p><img src="`+i+`" alt="" width="663" height="800"></p>`,22)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};